package com.grandvista.room.media;

import java.io.InputStream;
import java.util.Optional;

/**
 * Storage abstraction for room photographs. The development implementation writes to the local file
 * system; a production deployment can provide an object-store implementation (e.g. S3/Azure Blob)
 * without changing callers. Keys are generated by the storage, never taken from clients.
 */
public interface MediaStorage {

    StoredMedia store(byte[] content, ImageType type);

    Optional<MediaResource> load(String key);

    void delete(String key);

    record StoredMedia(String key, ImageType type, int sizeBytes) {
    }

    record MediaResource(String key, ImageType type, long sizeBytes, InputStream content) {
    }
}
